import{_ as t,o as a,c as n,a4 as l}from"./chunks/framework.BWWfBZka.js";const u=JSON.parse('{"title":"System Design Resource Kit","description":"","frontmatter":{},"headers":[],"relativePath":"en/01_Read_Me.md","filePath":"en/01_Read_Me.md","lastUpdated":1788996924000}'),s={name:"en/01_Read_Me.md"};function o(i,e,r,d,c,g){return a(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="system-design-resource-kit" tabindex="-1">System Design Resource Kit <a class="header-anchor" href="#system-design-resource-kit" aria-label="Permalink to &quot;System Design Resource Kit&quot;">​</a></h1><blockquote><p><strong>Building Blocks to Case Studies to Offer | High Level and Low Level Design</strong></p></blockquote><hr><h2 id="📌-what-this-is" tabindex="-1">📌 What This Is <a class="header-anchor" href="#📌-what-this-is" aria-label="Permalink to &quot;📌 What This Is&quot;">​</a></h2><p>Everything needed to clear the design round: fundamentals, every building block, 36 worked case studies, real company architectures, low level design, and the questions interviewers actually ask. DSA gets you the first offer. System design decides the level, the title and the salary band.</p><hr><h2 id="🧭-how-to-use-it" tabindex="-1">🧭 How To Use It <a class="header-anchor" href="#🧭-how-to-use-it" aria-label="Permalink to &quot;🧭 How To Use It&quot;">​</a></h2><ol><li><p>Open &#39;Roadmap&#39; first. It sequences 52 weeks from prerequisites through to company-specific preparation.</p></li><li><p>Learn &#39;Building Blocks&#39; before attempting any case study. You cannot design with components you cannot name.</p></li><li><p>&#39;Case Studies&#39; is the core sheet. Each one gives what to clarify, the components, the real bottleneck, and the follow-ups you will be asked.</p></li><li><p>Attempt each case study on a blank page BEFORE reading any solution. Reading solutions feels productive and teaches very little.</p></li><li><p>&#39;Engineering Blogs&#39; is what separates a textbook answer from a credible one. Read two posts a week, permanently.</p></li><li><p>&#39;Interview Prep&#39; and &#39;Companies Hiring&#39; are for the final phase. The Companies sheet tells you at which level each company starts asking.</p></li></ol><hr><h2 id="💡-the-honest-advice" tabindex="-1">💡 The Honest Advice <a class="header-anchor" href="#💡-the-honest-advice" aria-label="Permalink to &quot;💡 The Honest Advice&quot;">​</a></h2><ul><li>There is no correct design. There are only justified ones. Every unexplained component invites a challenge you will lose.</li><li>Structure beats knowledge. Requirements, estimation, high level, deep dive, wrap up. Most candidates fail on time management, not on knowing less.</li><li>Say what breaks. Every box you draw can fail. Candidates who volunteer the failure story before being asked score significantly higher.</li><li>Do not over-engineer. Reaching for Kafka and microservices on a problem that needs one server and a database is a failure, not a flourish.</li><li>Read real engineering blogs. The gap between textbook design and production reality is where senior candidates separate themselves.</li><li>Low level design is not optional in India. Amazon and most Indian product companies ask parking lot, elevator and BookMyShow directly.</li></ul><hr><h2 id="👤-built-by" tabindex="-1">👤 Built By <a class="header-anchor" href="#👤-built-by" aria-label="Permalink to &quot;👤 Built By&quot;">​</a></h2><ul><li><strong>Author</strong>: Avinash Singh, founder of Let&#39;s Code (lets-code.co.in): free AI career tools, 1000+ resources and a community of 100k+ engineers.</li><li><strong>Follow on X</strong>: Follow on X for updates and new resource drops: <a href="https://x.com/AvinashSingh_20" target="_blank" rel="noreferrer">https://x.com/AvinashSingh_20</a></li><li><strong>Resources</strong>: See the Lets Code Resources sheet for the free system design guide, DSA sheets and the full toolkit.</li></ul><hr><h2 id="🏷️-level-key" tabindex="-1">🏷️ Level Key <a class="header-anchor" href="#🏷️-level-key" aria-label="Permalink to &quot;🏷️ Level Key&quot;">​</a></h2><blockquote><p>Foundation = you cannot skip it. Core = expected in every design round. Advanced = senior and staff-level differentiators.</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">Level</th><th style="text-align:left;">Definition</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Foundation</strong></td><td style="text-align:left;">You cannot skip it</td></tr><tr><td style="text-align:left;"><strong>Core</strong></td><td style="text-align:left;">Expected in every design round</td></tr><tr><td style="text-align:left;"><strong>Advanced</strong></td><td style="text-align:left;">Senior and staff-level differentiators</td></tr></tbody></table><hr><h2 id="📑-table-of-contents" tabindex="-1">📑 Table of Contents <a class="header-anchor" href="#📑-table-of-contents" aria-label="Permalink to &quot;📑 Table of Contents&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Sheet / Module</th><th style="text-align:left;">What is in it</th><th style="text-align:center;">Entries</th><th style="text-align:left;">Document Link</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong><a href="./02_Skills_Matrix">Skills Matrix</a></strong></td><td style="text-align:left;">Every system design concept, with why it matters and how it is tested</td><td style="text-align:center;">99</td><td style="text-align:left;"><a href="./02_Skills_Matrix"><code>02_Skills_Matrix.md</code></a></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong><a href="./03_Roadmap">Roadmap</a></strong></td><td style="text-align:left;">52-week plan from prerequisites to company-specific preparation</td><td style="text-align:center;">14</td><td style="text-align:left;"><a href="./03_Roadmap"><code>03_Roadmap.md</code></a></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong><a href="./04_Case_Studies">Case Studies</a></strong></td><td style="text-align:left;">36 worked problems: what to clarify, components, bottleneck, follow-ups</td><td style="text-align:center;">36</td><td style="text-align:left;"><a href="./04_Case_Studies"><code>04_Case_Studies.md</code></a></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong><a href="./05_Building_Blocks">Building Blocks</a></strong></td><td style="text-align:left;">Every component: what it does, when to use it, when NOT to</td><td style="text-align:center;">42</td><td style="text-align:left;"><a href="./05_Building_Blocks"><code>05_Building_Blocks.md</code></a></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong><a href="./06_Engineering_Blogs">Engineering Blogs</a></strong></td><td style="text-align:left;">How real companies actually built it, by company and topic</td><td style="text-align:center;">35</td><td style="text-align:left;"><a href="./06_Engineering_Blogs"><code>06_Engineering_Blogs.md</code></a></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong><a href="./07_Free_Courses">Free Courses</a></strong></td><td style="text-align:left;">Free courses, reference architectures and university material</td><td style="text-align:center;">46</td><td style="text-align:left;"><a href="./07_Free_Courses"><code>07_Free_Courses.md</code></a></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong><a href="./08_YouTube">YouTube</a></strong></td><td style="text-align:left;">Direct playlists by topic, from the best system design teachers</td><td style="text-align:center;">36</td><td style="text-align:left;"><a href="./08_YouTube"><code>08_YouTube.md</code></a></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong><a href="./09_GitHub_Resources">GitHub Resources</a></strong></td><td style="text-align:left;">Curated indexes, written courses and low level design collections</td><td style="text-align:center;">35</td><td style="text-align:left;"><a href="./09_GitHub_Resources"><code>09_GitHub_Resources.md</code></a></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong><a href="./10_Books_and_Docs">Books &amp; Docs</a></strong></td><td style="text-align:left;">Books, foundational papers and the newsletters worth reading</td><td style="text-align:center;">37</td><td style="text-align:left;"><a href="./10_Books_and_Docs"><code>10_Books_and_Docs.md</code></a></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong><a href="./11_Interview_Prep">Interview Prep</a></strong></td><td style="text-align:left;">The questions actually asked, and what each one tests</td><td style="text-align:center;">67</td><td style="text-align:left;"><a href="./11_Interview_Prep"><code>11_Interview_Prep.md</code></a></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong><a href="./12_Communities">Communities</a></strong></td><td style="text-align:left;">Communities, creators, conferences and mock interview platforms</td><td style="text-align:center;">37</td><td style="text-align:left;"><a href="./12_Communities"><code>12_Communities.md</code></a></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong><a href="./13_Companies_Hiring">Companies Hiring</a></strong></td><td style="text-align:left;">At what level each company starts asking, and what they focus on</td><td style="text-align:center;">67</td><td style="text-align:left;"><a href="./13_Companies_Hiring"><code>13_Companies_Hiring.md</code></a></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong><a href="./14_Lets_Code_Resources">Lets Code Resources</a></strong></td><td style="text-align:left;">Free AI tools, prep material and community from Lets Code</td><td style="text-align:center;">34</td><td style="text-align:left;"><a href="./14_Lets_Code_Resources"><code>14_Lets_Code_Resources.md</code></a></td></tr><tr><td style="text-align:center;"></td><td style="text-align:left;"><strong>TOTAL RESOURCES</strong></td><td style="text-align:left;"></td><td style="text-align:center;"><strong>585</strong></td><td style="text-align:left;"></td></tr></tbody></table><hr><h2 id="i️-notes-compilation" tabindex="-1">ℹ️ Notes &amp; Compilation <a class="header-anchor" href="#i️-notes-compilation" aria-label="Permalink to &quot;ℹ️ Notes &amp; Compilation&quot;">​</a></h2><blockquote><p>Links compiled July 2026. Every YouTube URL is a direct playlist or video sourced from curated public indexes, not reconstructed from memory, and there are no channel-only links. Note that much of the best system design video content lives on channels rather than structured playlists, so the Free Courses, GitHub and Engineering Blogs sheets carry more weight here than in other vaults. Company difficulty and level thresholds are drawn from publicly reported interview experiences and vary by team, level and year.</p></blockquote>',24)])])}const y=t(s,[["render",o]]);export{u as __pageData,y as default};
